class Solution { struct Fenwick{vector<int> tree;Fenwick(int n):tree(n+1){}void add(int index,int delta){for(int i=index+1;i<(int)tree.size();i+=i&-i)tree[i]+=delta;}int query(int index){int sum=0;for(int i=index+1;i;i-=i&-i)sum+=tree[i];return sum;}};public:string minInteger(string num,int k){array<queue<int>,10> positions;Fenwick fenwick(num.size());for(int i=0;i<(int)num.size();++i){positions[num[i]-'0'].push(i);fenwick.add(i,1);}string answer;for(int output=0;output<(int)num.size();++output)for(int digit=0;digit<10;++digit)if(!positions[digit].empty()){int position=positions[digit].front(),cost=fenwick.query(position)-1;if(cost<=k){k-=cost;answer+=char('0'+digit);positions[digit].pop();fenwick.add(position,-1);break;}}return answer;} };
